496	function drawPriceChart(canvasId, priceData, color) {
497	  var canvas =
498	    typeof canvasId === "string" ? document.getElementById(canvasId) : canvasId;
499	  if (!canvas) return;
500	  var ctx = canvas.getContext("2d");
501	  var W = canvas.width,
502	    H = canvas.height;
503	  ctx.clearRect(0, 0, W, H);
504	
505	  var data = (priceData || []).slice(-20);
506	  if (data.length < 2) {
507	    ctx.fillStyle = "#999";
508	    ctx.font = "12px sans-serif";
509	    ctx.textAlign = "center";
510	    ctx.fillText("等待数据...", W / 2, H / 2);
511	    return;
512	  }
513	
514	  var prices = [];
515	  for (var i = 0; i < data.length; i++) prices.push(data[i].price);
516	
517	  var minP = prices[0],
518	    maxP = prices[0];
519	  for (var i = 1; i < prices.length; i++) {
520	    if (prices[i] < minP) minP = prices[i];
521	    if (prices[i] > maxP) maxP = prices[i];
522	  }
523	  var range = maxP - minP;
524	  if (range === 0) range = minP * 0.1 || 1;
525	  var padT = 4,
526	    padB = 4,
527	    padL = 4,
528	    padR = 4;
529	  var chartW = W - padL - padR;
530	  var chartH = H - padT - padB;
531	
532	  // 网格线
533	  if (ctx.strokeStyle) {
534	    ctx.strokeStyle = "rgba(255,255,255,0.06)";
535	    ctx.lineWidth = 0.5;
536	    for (var i = 0; i < 4; i++) {
537	      var y = padT + (chartH / 4) * i;
538	      ctx.beginPath();
539	      ctx.moveTo(padL, y);
540	      ctx.lineTo(W - padR, y);
541	      ctx.stroke();
542	    }
543	  }
544	
545	  // 折线
546	  var lineColor = color || "#4fc3f7";
547	  ctx.beginPath();
548	  ctx.strokeStyle = lineColor;
549	  ctx.lineWidth = 1.5;
550	  var firstX, firstY, lastX, lastY;
551	  for (var i = 0; i < prices.length; i++) {
552	    var x = padL + (i / (prices.length - 1)) * chartW;
553	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
554	    if (i === 0) {
555	      ctx.moveTo(x, y);
556	      firstX = x;
557	      firstY = y;
558	    } else {
559	      ctx.lineTo(x, y);
560	    }
561	    if (i === prices.length - 1) {
562	      lastX = x;
563	      lastY = y;
564	    }
565	  }
566	  ctx.stroke();
567	
568	  // 渐变填充
569	  var grad = ctx.createLinearGradient(0, padT, 0, H - padB);
570	  grad.addColorStop(0, lineColor + "30");
571	  grad.addColorStop(1, lineColor + "02");
572	  ctx.fillStyle = grad;
573	  ctx.beginPath();
574	  ctx.moveTo(firstX, H - padB);
575	  for (var i = 0; i < prices.length; i++) {
576	    var x = padL + (i / (prices.length - 1)) * chartW;
577	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
578	    if (i === 0) ctx.lineTo(x, y);
579	    else ctx.lineTo(x, y);
580	  }
581	  ctx.lineTo(lastX, H - padB);
582	  ctx.closePath();
583	  ctx.fill();
584	
585	  // 当前价格
586	  var lastPrice = prices[prices.length - 1];
587	  var prevPrice = prices.length >= 2 ? prices[prices.length - 2] : lastPrice;
588	  var chg = lastPrice - prevPrice;
589	  var chgPct = prevPrice !== 0 ? ((chg / prevPrice) * 100).toFixed(2) : "0.00";
590	  var chgText = (chg >= 0 ? "+" : "") + chgPct + "%";
591	
592	  ctx.fillStyle = lineColor;
593	  ctx.font = "bold 11px sans-serif";
594	  ctx.textAlign = "left";
595	  ctx.fillText(lastPrice.toFixed(2), padL + 2, padT + 10);
596	
597	  ctx.fillStyle = chg >= 0 ? "#4caf50" : "#f44336";
598	  ctx.font = "9px sans-serif";
599	  ctx.fillText(chgText, padL + 2, padT + 21);
600	}
