219	  p.corporate.upwardMgmt = Math.min(
220	    100,
221	    Math.round(state.skills.sales.level * 0.8 + 15),
222	  );
223	  p.corporate.kpi = Math.min(
224	    150,
225	    Math.round(p.agility * 0.5 + state.skills.coding.level * 0.5 + 15),
226	  );
227	  p.corporate.ability = Math.min(
228	    100,
229	    Math.round(p.intelligence * 0.8 + state.skills.coding.level * 0.5 + 10),
230	  );
231	  p.corporate.risk = Math.min(100, 8 + Math.floor(Math.random() * 12));
232	  p.corporate.popularity = Math.min(
233	    100,
234	    Math.round(state.status.fame * 0.5 + 25),
235	  );
