155	/** 初始化股市 */
156	function initStockMarket(state) {
157	  for (const stock of STOCK_LIST) {
158	    state.corporate.stockMarket[stock.symbol] = {
159	      price: stock.basePrice * (0.85 + Math.random() * 0.3),
160	      history: [], // [{ day, price }]
161	      high20: stock.basePrice,
162	      low20: stock.basePrice,
163	      lastNewsDay: -999,
164	      _initialized: false,
165	    };
166	  }
167	}
168	
169	/** 初始化时填入少量历史走势 */
170	function bootstrapStockHistory(state) {
171	  for (const sym of Object.keys(state.corporate.stockMarket)) {
172	    const market = state.corporate.stockMarket[sym];
173	    const def = STOCK_LIST.find((s) => s.symbol === sym);
174	    if (!def) continue;
175	    if (!market._initialized) {
176	      market._initialized = true;
177	      // 倒推 20 天历史
178	      let p = market.price / (0.85 + Math.random() * 0.3);
179	      for (let i = 0; i < 20; i++) {
180	        const change = 1 + (Math.random() - 0.5) * def.volatility;
181	        p = p * change;
182	        market.history.push({ day: state.player.day - (20 - i), price: p });
183	      }
184	      market.history.push({ day: state.player.day, price: market.price });
185	      market.high20 = Math.max(...market.history.map((h) => h.price));
186	      market.low20 = Math.min(...market.history.map((h) => h.price));
187	    }
188	  }
189	}
