171	function tickInvestmentDaily(state) {
172	  const inv = state.investment;
173	  if (!inv || inv.lastTickDay >= state.player.day) return;
174	  inv.lastTickDay = state.player.day;
175	  for (const s of INV_STOCKS) {
176	    const m = inv.stockMarket[s.symbol];
177	    if (!m) continue;
178	    m.price = Math.max(
179	      0.5,
180	      m.price * (1 + s.trend + (Math.random() - 0.5) * 2 * s.volatility),
181	    );
182	    m.price = Math.round(m.price * 100) / 100;
183	    m.history.push({ day: state.player.day, price: m.price });
184	    if (m.history.length > 20) m.history.shift();
185	  }
186	  if (inv.btcPrice > 0) {
187	    inv.btcFearGreed = Math.max(
188	      5,
189	      Math.min(95, (inv.btcFearGreed || 50) + (Math.random() - 0.5) * 10),
190	    );
191	    inv.btcPrice = Math.max(
192	      1000,
193	      Math.round(
194	        inv.btcPrice *
195	          (1 +
196	            (Math.random() - 0.5) * 0.08 +
197	            ((inv.btcFearGreed - 50) / 50) * 0.02),
198	      ),
199	    );
200	    if (state.player.day - inv.btcHalvingDay > 1460) {
201	      inv.btcHalvingDay = state.player.day;
202	      inv.btcFearGreed = Math.min(95, inv.btcFearGreed + 20);
203	      StateManager.addMessage("比特币减半事件！", "event");
204	    }
205	  }
206	  for (const p of inv.properties || []) {
207	    p.currentPrice = Math.round(
208	      (p.currentPrice || p.buyPrice) *
209	        (1 + p.appreciation + (Math.random() - 0.5) * 0.002),
210	    );
211	    if (state.player.day % 30 === 0) state.resources.cash += p.rent || 0;
212	  }
213	  for (const c of inv.cars || []) {
214	    c.currentPrice = Math.round(
215	      (c.currentPrice || c.buyPrice) * (1 - c.depreciation),
