250	// ============================================================
251	//  Canvas 涨跌曲线图
252	// ============================================================
253	function drawPriceChart(canvasId, priceData, color) {
254	  var canvas = typeof canvasId === "string" ? document.getElementById(canvasId) : canvasId;
255	  if (!canvas) return;
256	  var ctx = canvas.getContext("2d");
257	  var W = canvas.width, H = canvas.height;
258	  ctx.clearRect(0, 0, W, H);
259	
260	  var data = (priceData || []).slice(-20);
261	  if (data.length < 2) {
262	    ctx.fillStyle = "#999";
263	    ctx.font = "12px sans-serif";
264	    ctx.textAlign = "center";
265	    ctx.fillText("等待数据...", W / 2, H / 2);
266	    return;
267	  }
268	
269	  var prices = [];
270	  for (var i = 0; i < data.length; i++) prices.push(data[i].price);
271	
272	  var minP = prices[0], maxP = prices[0];
273	  for (var i = 1; i < prices.length; i++) {
274	    if (prices[i] < minP) minP = prices[i];
275	    if (prices[i] > maxP) maxP = prices[i];
276	  }
277	  var range = maxP - minP;
278	  if (range === 0) range = minP * 0.1 || 1;
279	  var padT = 4, padB = 4, padL = 4, padR = 4;
280	  var chartW = W - padL - padR;
281	  var chartH = H - padT - padB;
282	
283	  // 网格线
284	  if (ctx.strokeStyle) {
285	    ctx.strokeStyle = "rgba(255,255,255,0.06)";
286	    ctx.lineWidth = 0.5;
287	    for (var i = 0; i < 4; i++) {
288	      var y = padT + (chartH / 4) * i;
289	      ctx.beginPath();
290	      ctx.moveTo(padL, y);
291	      ctx.lineTo(W - padR, y);
292	      ctx.stroke();
293	    }
294	  }
295	
296	  // 折线
297	  var lineColor = color || "#4fc3f7";
298	  ctx.beginPath();
299	  ctx.strokeStyle = lineColor;
300	  ctx.lineWidth = 1.5;
301	  var firstX, firstY, lastX, lastY;
302	  for (var i = 0; i < prices.length; i++) {
303	    var x = padL + (i / (prices.length - 1)) * chartW;
304	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
305	    if (i === 0) {
306	      ctx.moveTo(x, y);
307	      firstX = x; firstY = y;
308	    } else {
309	      ctx.lineTo(x, y);
310	    }
311	    if (i === prices.length - 1) { lastX = x; lastY = y; }
312	  }
313	  ctx.stroke();
314	
315	  // 渐变填充
316	  var grad = ctx.createLinearGradient(0, padT, 0, H - padB);
317	  grad.addColorStop(0, lineColor + "30");
318	  grad.addColorStop(1, lineColor + "02");
319	  ctx.fillStyle = grad;
320	  ctx.beginPath();
321	  ctx.moveTo(firstX, H - padB);
322	  for (var i = 0; i < prices.length; i++) {
323	    var x = padL + (i / (prices.length - 1)) * chartW;
324	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
325	    if (i === 0) ctx.lineTo(x, y);
326	    else ctx.lineTo(x, y);
327	  }
328	  ctx.lineTo(lastX, H - padB);
329	  ctx.closePath();
330	  ctx.fill();
331	
332	  // 当前价格
333	  var lastPrice = prices[prices.length - 1];
334	  var prevPrice = prices.length >= 2 ? prices[prices.length - 2] : lastPrice;
335	  var chg = lastPrice - prevPrice;
336	  var chgPct = prevPrice !== 0 ? ((chg / prevPrice) * 100).toFixed(2) : "0.00";
337	  var chgText = (chg >= 0 ? "+" : "") + chgPct + "%";
338	
339	  ctx.fillStyle = lineColor;
340	  ctx.font = "bold 11px sans-serif";
341	  ctx.textAlign = "left";
342	  ctx.fillText(lastPrice.toFixed(2), padL + 2, padT + 10);
343	
344	  ctx.fillStyle = chg >= 0 ? "#4caf50" : "#f44336";
345	  ctx.font = "9px sans-serif";
346	  ctx.fillText(chgText, padL + 2, padT + 21);
347	}
