200	// ====== 状态管理器 ======
201	class GameStateManager {
202	  constructor() {
203	    this._state = null;
204	    this._dirtyFlags = new Set();
205	    this._listeners = [];
206	  }
207	
208	  /** 初始化新游戏 */
209	  newGame() {
210	    this._state = createDefaultState();
211	    this._markAllDirty();
212	    this._notify();
213	    return this._state;
214	  }
215	
216	  /** 获取当前完整状态（只读引用，请勿直接修改嵌套对象） */
217	  getState() {
218	    if (!this._state) {
219	      throw new Error(
220	        "GameState not initialized. Call newGame() or loadGame() first.",
221	      );
222	    }
223	    return this._state;
224	  }
225	
226	  /** 获取状态某个路径的值 */
227	  get(path) {
228	    const parts = path.split(".");
229	    let val = this.getState();
230	    for (const p of parts) {
231	      if (val == null) return undefined;
232	      val = val[p];
233	    }
234	    return val;
235	  }
236	
237	  /**
238	   * 更新状态某个路径的值
239	   * 用法: update('player.age', 25) 或 update('player', { age: 25, ... })
240	   */
241	  update(path, value) {
242	    const parts = path.split(".");
243	    const state = this.getState();
244	
245	    // 导航到父对象
246	    let parent = state;
247	    for (let i = 0; i < parts.length - 1; i++) {
248	      parent = parent[parts[i]];
249	    }
250	
251	    const key = parts[parts.length - 1];
252	    parent[key] = value;
253	
254	    // 标记脏路径
255	    this._dirtyFlags.add(path);
256	    this._notify();
257	  }
258	
259	  /** 批量更新（用于一次性修改多个字段） */
260	  batchUpdate(updates) {
261	    for (const [path, value] of Object.entries(updates)) {
262	      const parts = path.split(".");
263	      const state = this.getState();
264	      let parent = state;
265	      for (let i = 0; i < parts.length - 1; i++) {
266	        parent = parent[parts[i]];
267	      }
268	      parent[parts[parts.length - 1]] = value;
269	      this._dirtyFlags.add(path);
270	    }
271	    this._notify();
272	  }
273	
274	  /** 添加消息到日志 */
275	  addMessage(text, type = "info") {
276	    const state = this.getState();
277	    state.messageLog.push({
278	      day: state.player.day,
279	      text,
280	      type, // 'info'|'success'|'danger'|'event'|'warning'
281	    });
282	    // 限制日志长度
283	    if (state.messageLog.length > 500) {
284	      state.messageLog = state.messageLog.slice(-300);
285	    }
286	    this._dirtyFlags.add("messageLog");
287	    this._notify();
288	  }
289	
290	  /** 导入存档 */
291	  importState(savedState) {
292	    this._state = savedState;
293	    this._state.lastPlayedAt = Date.now();
294	    this._markAllDirty();
295	    this._notify();
296	  }
297	
298	  /** 检查路径是否脏（自上次 cleanDirty 后） */
299	  isDirty(path) {
300	    return this._dirtyFlags.has(path);
301	  }
302	
303	  /** 清除所有脏标记（渲染后调用） */
304	  cleanAllDirty() {
305	    this._dirtyFlags.clear();
306	  }
307	
308	  /** 订阅状态变更 */
309	  onChange(callback) {
310	    this._listeners.push(callback);
311	  }
312	
313	  // ====== 内部方法 ======
314	  _markAllDirty() {
315	    this._dirtyFlags.add("*");
316	  }
317	
318	  _notify() {
319	    for (const cb of this._listeners) {
320	      try {
321	        cb(this._state);
322	      } catch (e) {
323	        /* 静默 */
324	      }
325	    }
326	  }
327	}
328	
329	// ====== 单例导出 ======
330	const StateManager = new GameStateManager();
331	
332	// 使其在全局可访问（方便调试）
333	if (typeof window !== "undefined") {
334	  window.StateManager = StateManager;
335	}
