550	  var firstX, firstY, lastX, lastY;
551	  for (var i = 0; i < prices.length; i++) {
552	    var x = padL + (i / (prices.length - 1)) * chartW;
553	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
554	    if (i === 0) {
555	      ctx.moveTo(x, y);
556	      firstX = x;
557	      firstY = y;
558	    } else {
559	      ctx.lineTo(x, y);
560	    }
561	    if (i === prices.length - 1) {
562	      lastX = x;
563	      lastY = y;
564	    }
565	  }
566	  ctx.stroke();
567	
568	  // 渐变填充
569	  var grad = ctx.createLinearGradient(0, padT, 0, H - padB);
570	  grad.addColorStop(0, lineColor + "30");
571	  grad.addColorStop(1, lineColor + "02");
572	  ctx.fillStyle = grad;
573	  ctx.beginPath();
574	  ctx.moveTo(firstX, H - padB);
575	  for (var i = 0; i < prices.length; i++) {
576	    var x = padL + (i / (prices.length - 1)) * chartW;
577	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
578	    if (i === 0) ctx.lineTo(x, y);
579	    else ctx.lineTo(x, y);
580	  }
581	  ctx.lineTo(lastX, H - padB);
582	  ctx.closePath();
583	  ctx.fill();
584	
585	  // 当前价格
586	  var lastPrice = prices[prices.length - 1];
587	  var prevPrice = prices.length >= 2 ? prices[prices.length - 2] : lastPrice;
588	  var chg = lastPrice - prevPrice;
589	  var chgPct = prevPrice !== 0 ? ((chg / prevPrice) * 100).toFixed(2) : "0.00";
590	  var chgText = (chg >= 0 ? "+" : "") + chgPct + "%";
591	
592	  ctx.fillStyle = lineColor;
593	  ctx.font = "bold 11px sans-serif";
594	  ctx.textAlign = "left";
595	  ctx.fillText(lastPrice.toFixed(2), padL + 2, padT + 10);
596	
597	  ctx.fillStyle = chg >= 0 ? "#4caf50" : "#f44336";
598	  ctx.font = "9px sans-serif";
599	  ctx.fillText(chgText, padL + 2, padT + 21);
600	}
